changeSet.sql:
ALTER TABLE branches ENABLE ROW LEVEL SECURITY;
ALTER TABLE branches FORCE ROW LEVEL SECURITY;

CREATE POLICY branches_platform ON branches FOR ALL
    USING (current_setting('landvault.platform_scope', true) = 'on')
    WITH CHECK (current_setting('landvault.platform_scope', true) = 'on');

CREATE POLICY branches_tenant ON branches FOR ALL
    USING (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND organization_id::text = current_setting('landvault.tenant_id', true)
        AND (
            current_setting('landvault.branch_id', true) IS NULL
            OR current_setting('landvault.branch_id', true) = ''
            OR id::text = current_setting('landvault.branch_id', true)
        )
    )
    WITH CHECK (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND organization_id::text = current_setting('landvault.tenant_id', true)
    );

changeSet.rollback:
DROP POLICY IF EXISTS branches_platform ON branches;
DROP POLICY IF EXISTS branches_tenant ON branches;
ALTER TABLE branches NO FORCE ROW LEVEL SECURITY;
ALTER TABLE branches DISABLE ROW LEVEL SECURITY;
